export const FLASHOVER_REFERENCE=20;
export function resetFlashover(s){s.flashover=Array.from({length:5},()=>({flux:null,active:false,progress:0}));}
export function canFlashover(f){return Number.isFinite(f.flux)&&f.flux>=FLASHOVER_REFERENCE&&!f.active;}
export function stepFlashover(s,dt){for(let i=0;i<5;i++){const f=s.flashover[i];f.progress=Math.max(0,Math.min(1,f.progress+dt*(f.active?.25:-.5)));if(f.active){s.floors[i]=Math.max(s.floors[i],f.progress*.9);s.depths[i]=Math.max(s.depths[i],f.progress*2.4);}}}
export function addFlashoverControls(s,{log,isEnded,isRunning}){const panel=document.createElement('section');panel.className='flashover-panel';panel.innerHTML=`<h3>閃燃情境</h3><label>指定樓層<select id="flashFloor">${[1,2,3,4,5].map(f=>`<option value="${f-1}" ${f===3?'selected':''}>${f} 樓</option>`).join('')}</select></label><label>地板處熱通量（教官輸入，kW/m²）<input id="flashFlux" type="number" min="0" max="200" step="0.5" placeholder="尚未輸入"></label><button id="fluxApply">套用熱通量</button><p id="fluxState" role="status"></p><div id="flashChoice" hidden><strong>已達 20 kW/m² 參考門檻</strong><p>是否觸發此樓層的全面燃燒情境？</p><button id="flashTrigger">觸發本層閃燃</button></div><button id="flashStop">停止本層閃燃示意</button><p class="note">熱通量由教官輸入，並非由 t² 熱釋放率自動換算。20 kW/m² 為文獻參考指標，並非必然發生閃燃的充分條件。整層燃燒是情境放大呈現，不代表各分隔房間同時閃燃；不另外計算閃燃後熱釋放率。演練暫停時凍結動畫。</p><a href="https://tsapps.nist.gov/publication/get_pdf.cfm?pub_id=861187" target="_blank" rel="noopener">閃燃指標與不確定性：研究依據</a>`;document.querySelector('.fire-controls').append(panel);const $=q=>panel.querySelector(q),floor=()=>Number($('#flashFloor').value);
function update(){const f=s.flashover[floor()];$('#flashChoice').hidden=!canFlashover(f);$('#flashTrigger').disabled=isEnded()||!isRunning()||!canFlashover(f);$('#flashStop').disabled=isEnded()||!f.active;$('#fluxApply').disabled=isEnded();$('#flashFlux').disabled=isEnded();$('#flashFloor').disabled=isEnded();$('#fluxState').textContent=f.active?'本層閃燃情境進行中':f.flux===null?'尚未輸入熱通量，不作閃燃門檻判定。':`本層 ${f.flux} kW/m² · ${canFlashover(f)?'可手動觸發（需演練進行中）':'未達參考門檻；不代表安全'}`;}
$('#flashFloor').onchange=()=>{$('#flashFlux').value=s.flashover[floor()].flux??'';update()};$('#fluxApply').onclick=()=>{if(isEnded())return;const input=$('#flashFlux'),f=s.flashover[floor()],v=input.valueAsNumber;if(input.value===''){f.flux=null;update();return}if(!Number.isFinite(v)||v<0||v>200){$('#fluxState').textContent='請輸入 0–200 kW/m² 的有限數值。';return}f.flux=v;log('熱通量設定',`${floor()+1} 樓：教官輸入 ${v} kW/m²`);update()};$('#flashTrigger').onclick=()=>{const f=s.flashover[floor()];if(isEnded()||!isRunning()||!canFlashover(f))return;f.active=true;log('閃燃情境',`${floor()+1} 樓達教官輸入熱通量 ${f.flux} kW/m²；手動觸發整層燃燒示意。`,true);update()};$('#flashStop').onclick=()=>{if(isEnded())return;s.flashover[floor()].active=false;log('閃燃情境',`${floor()+1} 樓停止閃燃示意（非滅火判定）。`);update()};update();return {update};}
